<template>
  <main class="bi-page">
    <ModuleHeader :title="auth.ownSales ? t('mySales') : t('title')">
      <button class="erp-button erp-button--secondary" v-if="!auth.ownSales" @click="tab = 'sources'">
        <Database :size="16" />
        {{ t("sources") }}
      </button>
      <button
        class="primary erp-button erp-button--primary"
        :disabled="refreshing || status?.running || !status?.configured || !status?.enabled"
        @click="refresh"
      >
        <RefreshCw :size="16" :class="{ spin: status?.running }" />
        {{ status?.running ? t("updating") : t("updateData") }}
      </button>
    </ModuleHeader>
    <div v-if="error" role="alert" class="alert error">{{sourceMessage(error)}}<button class="erp-button erp-button--ghost erp-button--icon" :aria-label="t('closeNotice')" @click="error=''">×</button></div>
    <div v-if="notice" role="status" class="alert success">{{t(notice)}}<button class="erp-button erp-button--ghost erp-button--icon" :aria-label="t('closeNotice')" @click="notice=''">×</button></div>
    <div class="sync-line"><span :class="['dot', {working:status?.running, warning:!!status?.error}]"/><span>{{ status?.running ? t('readingOneDrive') : status?.finished_at ? t('lastCheck',{date:date(status.finished_at)}) : t('waitingFirst') }}</span><span class="sync-detail">{{t('dailySchedule')}}</span></div>
    <div v-if="status?.error" class="alert caution" role="status"><span>{{t('sourceFailure')}}</span><button class="erp-button erp-button--secondary" v-if="!auth.ownSales" @click="tab='sources'">{{t('viewSources')}}</button></div>
    <nav class="tabs" :aria-label="t('analysisNav')"><button class="erp-control" v-for="t in tabs" :key="t.id" :class="{selected:tab===t.id}" @click="tab=t.id"><component :is="t.icon" :size="17"/>{{t.label}}</button></nav>

    <section v-if="tab !== 'sources'" class="filters" :aria-label="t('filters')">
      <label>{{t('year')}}<select v-model.number="year" @change="load"><option :value="0">{{t('allHistory')}}</option><option v-for="y in data?.years" :key="y" :value="y">{{y}}</option></select></label>
      <label>{{t('month')}}<select v-model.number="month" @change="load"><option :value="0">{{t('allMonths')}}</option><option v-for="(m,i) in monthNames" :key="m" :value="i+1">{{m}}</option></select></label>
      <label>{{t('seller')}}<select v-model="seller" :disabled="auth.ownSales" @change="load"><option v-if="!auth.ownSales" value="">{{t('allTeam')}}</option><option v-for="s in data?.sellers" :key="s">{{s}}</option></select></label>
      <div class="filter-caption"><span class="badge">{{periodLabel}}</span><small>{{t('totalsHelp')}}</small></div>
    </section>
    <div v-if="loading && !data" class="empty panel"><RefreshCw class="spin" :size="28"/><h2>{{t('loading')}}</h2></div>
    <section v-else-if="data && !data.years.length && tab!=='sources'" class="empty panel"><BarChart3 :size="38"/><h2>{{status?.running?t('readingHistory'):t('startInExcel')}}</h2><p>{{status?.configured?t('afterFirstRead'):t('connectToStart')}}</p><button class="erp-button erp-button--secondary" v-if="!auth.ownSales" @click="tab='sources'">{{t('followSources')}}</button></section>
    <template v-else-if="data && tab !== 'sources'">
      <div :aria-busy="loading" :class="{updating:loading}">
        <section class="metrics" :style="auth.ownSales ? {gridTemplateColumns:'repeat(3,minmax(0,1fr))'} : undefined">
          <article class="metric featured"><span>{{t('periodSales')}} <span v-if="data.selected.partial" class="badge">{{t('ongoing')}}</span></span><strong>{{usd(data.selected.total_usd)}}</strong><small>{{seller || t('allTeam')}} · {{t('availableMonths',{count:data.selected.available_months,total:data.selected.source_months})}}</small><TrendingUp :size="23"/></article>
          <article class="metric"><span>{{year ? t('yearTotal',{year}) : t('historyTotal')}}</span><strong>{{usd(annualTotal)}}</strong><small>{{t('monthsWithData',{count:annualCoverage})}}{{year===data.latest.year ? t('throughLatest') : ''}}</small><CalendarDays :size="21"/></article>
          <article v-if="!auth.ownSales" class="metric"><span>{{seller ? t('periodRank') : t('bestSeller')}}</span><strong class="name">{{seller ? sellerPosition : data.ranking[0]?.name || '—'}}</strong><small>{{seller ? seller : usd(data.ranking[0]?.total_usd)}} {{t('availableResults')}}</small><Trophy :size="21"/></article>
          <article class="metric"><span>{{t('bestWeek')}}</span><strong>{{usd(data.weeks[0]?.total_usd)}}</strong><small>{{data.weeks[0] ? `${weekLabel(data.weeks[0].label)} · ${data.weeks[0].year}` : t('noWeekAvailable')}}</small><ChartNoAxesCombined :size="21"/></article>
        </section>
        <p v-if="data.selected.available_months < data.selected.source_months || data.coverage.warnings" class="data-note"><Info :size="16"/><span>{{t('coverageNote')}} <span v-if="!auth.ownSales">{{t('seeWarnings')}} <button class="text-button erp-button erp-button--ghost" @click="tab='sources'">{{t('sources')}}</button>.</span></span></p>

        <template v-if="tab==='overview'">
          <div class="analysis-grid">
            <section class="panel trend-panel"><div class="section-head"><div><span class="eyebrow">{{t('trendEyebrow')}}</span><h2>{{t('monthlySales')}}</h2><p>{{seller || t('storeResult')}} · {{year || t('allYears')}}</p></div><span class="badge">US$</span></div><div class="chart"><Line :data="trendChart" :options="lineOptions" :aria-label="t('trendAria')" role="img"/></div><small>{{t('trendHelp')}}</small></section>
            <section class="panel ranking-panel"><div class="section-head"><div><span class="eyebrow">{{auth.ownSales ? t('mySales') : t('team')}}</span><h2>{{auth.ownSales ? t('personalResult') : t('sellerRanking')}}</h2><p>{{periodLabel}}</p></div><Users :size="21"/></div><div v-if="!data.ranking.length" class="empty small-empty">{{t('noSellerResults')}}</div><button v-for="(r,i) in data.ranking" :key="r.name" class="rank-row erp-control" :class="{chosen:seller===r.name}" @click="seller=auth.ownSales?r.name:seller===r.name?'':r.name;load()"><span v-if="!auth.ownSales" class="rank-index">{{i+1}}</span><div class="rank-content"><div><strong>{{r.name}}</strong><b>{{usd(r.total_usd)}}</b></div><div class="bar-track"><span :style="{width:rankWidth(r.total_usd)+'%'}"/></div><small>{{t('availableMonths',{count:r.available_months,total:r.source_months})}}</small></div></button></section>
          </div>
          <section class="panel currencies"><div class="section-head"><div><span class="eyebrow">{{t('currenciesEyebrow')}}</span><h2>{{t('currencyValues')}}</h2><p>{{t('currencyHelp')}}</p></div><Coins :size="22"/></div><div class="currency-grid"><article v-for="c in data.currencies" :key="c.currency"><span>{{currencyNames[c.currency]}}</span><strong>{{amount(c.value,c.currency)}}</strong><small>{{t('detailedMonths',{count:c.available_months,total:c.source_months})}}</small></article></div></section>
          <section class="panel"><div class="section-head"><div><h2>{{t('monthlyResults')}}</h2><p>{{t('oneMonthResult')}}</p></div><button class="erp-button erp-button--secondary" :disabled="!visibleMonths.length" @click="exportCsv"><Download :size="16"/>{{t('export')}}</button></div><div class="table-wrap"><table><thead><tr><th>{{t('period')}}</th><th>{{t('source')}}</th><th>{{t('dataUpdated')}}</th><th class="numeric">{{seller || t('storeTotal')}} · US$</th></tr></thead><tbody><tr v-for="m in visibleMonths" :key="`${m.year}-${m.month}`"><td><button class="text-button erp-button erp-button--ghost" @click="year=m.year;month=m.month;load()">{{monthNames[m.month-1]}} / {{m.year}}</button><span v-if="m.partial" class="badge partial">{{t('ongoing')}}</span></td><td>{{m.filename}}<small>{{m.source_cell || t('weeklySummaries')}}</small></td><td>{{date(m.synced_at)}}<small v-if="m.stale" class="warning-text">{{t('lastValid')}}</small></td><td class="numeric"><strong>{{usd(m.total_usd)}}</strong></td></tr></tbody></table><p v-if="!visibleMonths.length" class="empty">{{t('noMonthlyData')}}</p></div></section>
        </template>

        <SalesEntriesPanel v-if="tab==='entries'" :year="year" :month="month" :seller="seller" :refreshed-at="status?.finished_at" />

        <template v-if="tab==='compare'">
          <section class="panel"><div class="section-head"><div><span class="eyebrow">{{t('compareEyebrow')}}</span><h2>{{t('monthAcrossYears',{month:monthNames[data.comparison_month-1]})}}</h2><p>{{seller || t('allTeam')}} {{t('selectYears')}}</p></div></div><div class="year-chips"><label v-for="y in data.years" :key="y" :class="{on:compareYears.includes(y)}"><input v-model="compareYears" type="checkbox" :value="y"/>{{y}}</label></div><div class="chart comparison-chart"><Bar :data="comparisonChart" :options="barOptions" role="img" :aria-label="t('compareAria')"/></div><div class="table-wrap"><table><thead><tr><th>{{t('year')}}</th><th class="numeric">{{t('salesUsd')}}</th><th class="numeric">{{t('differenceYears')}}</th><th>{{t('status')}}</th></tr></thead><tbody><tr v-for="m in comparisonRows" :key="m.year"><td><strong>{{m.year}}</strong></td><td class="numeric">{{usd(m.total_usd)}}</td><td class="numeric"><span :class="{'positive':(m.delta||0)>0,'negative':(m.delta||0)<0}">{{m.delta===null ? '—' : `${m.delta>=0?'+':''}${usd(m.delta)}`}}</span><small v-if="m.previous">vs. {{m.previous}}{{m.percent===null ? '' : ` · ${m.percent.toLocaleString(locale,{maximumFractionDigits:1})}%`}}</small></td><td><span class="badge" :class="{partial:m.partial}">{{m.total_usd===null?t('noDetail'):m.partial?t('currentMonth'):t('monthlyFile')}}</span></td></tr></tbody></table></div><p v-if="comparisonRows.some(m=>m.partial)" class="data-note"><Info :size="16"/>{{t('partialComparison')}}</p></section>
          <section class="panel"><h2>{{t('annualTotal')}}</h2><p>{{t('annualHelp')}}</p><div class="table-wrap"><table><thead><tr><th>{{t('year')}}</th><th>{{t('monthsWithResult')}}</th><th class="numeric">{{seller || t('allTeam')}} · US$</th></tr></thead><tbody><tr v-for="a in data.annual" :key="a.year"><td><strong>{{a.year}}</strong></td><td>{{t('availableMonths',{count:a.available_months,total:a.source_months})}} <span v-if="a.partial" class="badge partial">{{t('ongoing')}}</span></td><td class="numeric">{{usd(a.total_usd)}}</td></tr></tbody></table></div></section>
        </template>

        <section v-if="tab==='weeks'" class="panel"><div class="section-head"><div><span class="eyebrow">{{t('highlights')}}</span><h2>{{t('bestWeeks')}}</h2><p>{{periodLabel}} · {{seller || t('allTeam')}}{{t('weeksHelp')}}</p></div><select v-model.number="weekLimit" :aria-label="t('weekQuantity')"><option :value="10">Top 10</option><option :value="25">Top 25</option><option :value="1000">{{t('all')}}</option></select></div><div class="table-wrap"><table><thead><tr><th>{{t('position')}}</th><th>{{t('week')}}</th><th>{{t('monthYear')}}</th><th class="numeric">{{t('salesUsd')}}</th></tr></thead><tbody><tr v-for="(w,i) in data.weeks.slice(0,weekLimit)" :key="`${w.year}-${w.month}-${w.index}`"><td><span class="rank-index" :class="{medal:i<3}">{{i+1}}</span></td><td><strong>{{weekLabel(w.label)}}</strong><small>{{t('worksheetPeriod',{index:w.index})}}</small></td><td>{{monthNames[w.month-1]}} / {{w.year}} <span v-if="w.partial" class="badge partial">{{t('currentMonth')}}</span></td><td class="numeric"><strong>{{usd(w.total_usd)}}</strong></td></tr></tbody></table><p v-if="!data.weeks.length" class="empty">{{t('noWeeks')}}</p></div></section>
      </div>
    </template>

    <template v-if="tab==='sources' && !auth.ownSales">
      <section class="panel source-intro"><div><span class="eyebrow">{{t('excelConnection')}}</span><h2>{{t('sourceTitle')}}</h2><p>{{t('sourceDescription')}}</p><p class="muted">{{t('sourceSchedule')}}</p></div><button class="erp-button erp-button--secondary" v-if="auth.user?.role==='ADMIN'" @click="openConfig"><Settings2 :size="16"/>{{t('configure')}}</button></section>
      <div v-if="configOpen" class="panel config-panel"><h2>{{t('oneDriveSources')}}</h2><form @submit.prevent="saveConfig"><label>{{t('currentLink')}}<input v-model="config.current_url" type="url" required autocomplete="off"/></label><label>{{t('archiveLink')}}<input v-model="config.archive_url" type="url" required autocomplete="off"/></label><label>{{t('archivePath')}}<input v-model="config.archive_root" required placeholder="/personal/…/Documents/…" autocomplete="off"/></label><p>{{t('folderHelp')}}</p><details><summary>{{t('currentPeriod')}}</summary><p>{{t('periodHelp')}}</p><div class="config-period"><label>{{t('year')}}<input v-model.number="config.current_year" type="number" min="2000" max="2100" :placeholder="t('automatic')"/></label><label>{{t('month')}}<select v-model="config.current_month"><option :value="null">{{t('automatic')}}</option><option v-for="(m,i) in monthNames" :key="m" :value="i+1">{{m}}</option></select></label></div></details><label class="check"><input v-model="config.enabled" type="checkbox"/>{{t('autoActive')}}</label><div class="form-actions"><button class="erp-button erp-button--secondary" type="button" @click="configOpen=false">{{t('close')}}</button><button type="submit" class="primary erp-button erp-button--primary" :disabled="saving || status?.running">{{saving?t('saving'):t('saveSources')}}</button></div></form></div>
      <section class="panel"><div class="section-head"><div><h2>{{t('readHistory')}}</h2><p>{{t('sourceCoverage',{sources:status?.sources.length||0,months:data?.coverage.months||0})}}</p></div><label class="check"><input v-model="onlyIssues" type="checkbox"/>{{t('showIssues')}}</label></div><div class="table-wrap"><table><thead><tr><th>{{t('spreadsheet')}}</th><th>{{t('period')}}</th><th>{{t('lastValid')}}</th><th>{{t('status')}}</th></tr></thead><tbody><tr v-for="s in visibleSources" :key="s.id"><td><strong>{{s.filename}}</strong><small>{{s.kind==='current'?t('currentSheet'):t('oneDriveArchive')}}</small></td><td>{{s.month ? monthNames[s.month-1] : '—'}} {{s.year || ''}}</td><td>{{date(s.synced_at)}}</td><td><span class="badge" :class="{'issue':!!s.error,'partial':!s.error && !!s.warnings.length}">{{s.error?t('readFailed'):!s.has_data?t('waitingRead'):!s.selected?t('alreadySelected'):s.warnings.length?t('checkSummaries'):t('updated')}}</span><small v-if="s.error" class="warning-text">{{sourceMessage(s.error)}}</small><details v-if="s.warnings.length"><summary>{{t('aboutData')}}</summary><p v-for="w in s.warnings" :key="w">{{sourceMessage(w)}}</p></details></td></tr></tbody></table><p v-if="!visibleSources.length" class="empty">{{onlyIssues?t('noIssues'):t('noSheets')}}</p></div></section>
    </template>
  </main>
</template>

<script setup lang="ts">
import ModuleHeader from '@/components/ModuleHeader.vue'
import {computed, onMounted, onUnmounted, ref, watch} from 'vue'
import { useRoute} from 'vue-router'
import {useI18n} from 'vue-i18n'
import messages from '@/components/sales/salesBi.messages.json'
import { BarChart3, CalendarDays, ChartNoAxesCombined, Coins, Database, Download, GitCompareArrows, Info, RefreshCw, Settings2, TrendingUp, Trophy, Users} from 'lucide-vue-next'
import {Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Tooltip, Legend, Filler, type ChartOptions} from 'chart.js'
import {Line, Bar} from 'vue-chartjs'
import {salesBi, type Overview, type SourceStatus, type SourceConfig} from '@/services/salesBi'
import SalesEntriesPanel from '@/components/sales/SalesEntriesPanel.vue'
import {useAuthStore} from '@/stores/auth'
ChartJS.register(CategoryScale,LinearScale,PointElement,LineElement,BarElement,Tooltip,Legend,Filler)
const {t,locale}=useI18n({useScope:'local',messages})
const auth=useAuthStore()
const route=useRoute()
const monthNames=computed(()=>Array.from({length:12},(_,month)=>new Date(2026,month,1).toLocaleDateString(locale.value,{month:'long'}).replace(/^./,c=>c.toUpperCase())))
const currencyNames=computed<Record<string,string>>(()=>({USD:t('usd'),BRL:t('brl'),PYG:t('pyg'),EUR:t('eur')}))
const palette=['#2563eb','#10b981','#8b5cf6','#f59e0b','#f43f5e','#64748b']
const tabs=computed(()=>[{id:'overview',label:t('overview'),icon:BarChart3},{id:'compare',label:t('compareMonths'),icon:GitCompareArrows},{id:'weeks',label:t('topWeeks'),icon:Trophy},{id:'entries',label:t('entries'),icon:Coins},{id:'sources',label:t('sources'),icon:Database}].filter(t=>!auth.ownSales||t.id!=='sources'))
const tab=ref('overview'),year=ref(0),month=ref(0),seller=ref(''),compareYears=ref<number[]>([]),weekLimit=ref(10)
const data=ref<Overview|null>(null),status=ref<SourceStatus|null>(null),loading=ref(false),refreshing=ref(false),saving=ref(false)
const error=ref(''),notice=ref(''),configOpen=ref(false),onlyIssues=ref(false)
const config=ref<SourceConfig>({current_url:'',archive_url:'',archive_root:'',current_year:null,current_month:null,enabled:true})
let sequence=0, timer:ReturnType<typeof setInterval>|undefined, polling=false, disposed=false
function applyDashboardLink(initial:Overview){
  const value=(key:string)=>typeof route.query[key]==='string'?route.query[key] as string:''
  const requestedTab=value('tab'),requestedYear=value('year'),requestedMonth=value('month')
  tab.value=tabs.value.some(t=>t.id===requestedTab)?requestedTab:'overview'
  year.value=requestedYear==='0'?0:initial.years.includes(Number(requestedYear))?Number(requestedYear):initial.latest.year||0
  month.value=/^(?:[0-9]|1[0-2])$/.test(requestedMonth)?Number(requestedMonth):initial.latest.month||0
  seller.value=auth.ownSales ? initial.access?.seller||auth.user?.sales_seller||'' : initial.sellers.includes(value('seller'))?value('seller'):''
}
watch(()=>route.query,()=>{if(data.value){applyDashboardLink(data.value);load()}})
const sourceKeys=new Map(Object.entries(messages.pt).map(([key,label])=>[label,key]))
function sourceMessage(value:string){
  const key=sourceKeys.get(value)
  if(key)return t(key)
  const difference=/^A soma por vendedor está US\$ ([\d.,]+) (acima|abaixo) do fechamento mensal\./.exec(value)
  if(difference)return t('warningDifference',{amount:usd(Number(difference[1].replaceAll('.','').replace(',','.'))),direction:t(difference[2]==='acima'?'above':'below')})
  return value
}
function weekLabel(value:string){const match=/^Semana (\d+)$/.exec(value);return match?`${t('week')} ${match[1]}`:value}
function explain(e:unknown){const detail=(e as {response?:{data?:{detail?:unknown}}})?.response?.data?.detail;return typeof detail==='string'?detail:messages.pt.queryError}
function usd(v:number|null|undefined){return v===null||v===undefined?'—':v.toLocaleString(locale.value,{style:'currency',currency:'USD',minimumFractionDigits:2})}
function amount(v:number|null,c:string){return v===null?'—':v.toLocaleString(locale.value,{style:'currency',currency:c,maximumFractionDigits:c==='PYG'?0:2})}
function date(v:string|null|undefined){return v?new Date(v).toLocaleString(locale.value,{dateStyle:'short',timeStyle:'short'}):'—'}
const periodLabel=computed(()=>`${month.value ? monthNames.value[month.value-1] : t('allMonths')} · ${year.value || t('allHistoryLower')}`)
const annualRows=computed(()=>data.value?.annual.filter(a=>!year.value||a.year===year.value)||[])
const annualTotal=computed(()=>{const vals=annualRows.value.filter(a=>a.total_usd!==null);return vals.length?vals.reduce((n,a)=>n+(a.total_usd||0),0):null})
const annualCoverage=computed(()=>annualRows.value.reduce((n,a)=>n+a.available_months,0))
const sellerPosition=computed(()=>{const i=data.value?.ranking.findIndex(r=>r.name===seller.value)??-1;return i<0?'—':t('rankPosition',{position:i+1})})
const visibleMonths=computed(()=>[...(data.value?.months||[])].filter(m=>(!year.value||m.year===year.value)&&(!month.value||m.month===month.value)).reverse())
const visibleSources=computed(()=>status.value?.sources.filter(s=>!onlyIssues.value||s.error||s.warnings.length)||[])
function rankWidth(v:number){return Math.max(0,Math.min(100,v/Math.max(1,data.value?.ranking[0]?.total_usd||1)*100))}
const trendYears=computed(()=>year.value?[year.value]:[...(data.value?.years||[])].reverse())
const trendChart=computed(()=>({labels:monthNames.value.map(m=>m.slice(0,3)),datasets:trendYears.value.map((y,i)=>({label:String(y),data:monthNames.value.map((_,n)=>data.value?.months.find(m=>m.year===y&&m.month===n+1)?.total_usd??null),borderColor:palette[i%palette.length],backgroundColor:palette[i%palette.length]+'15',pointRadius:3,pointHoverRadius:6,tension:.25,fill:trendYears.value.length===1,spanGaps:false,borderWidth:2.5}))}))
const comparisonRows=computed(()=>{const rows=(data.value?.comparison||[]).filter(m=>compareYears.value.includes(m.year));return rows.map((m,i)=>{const previous=rows[i-1],delta=m.total_usd!==null&&previous&&previous.total_usd!==null?m.total_usd-previous.total_usd:null;return {...m,delta,previous:previous?.year,percent:delta!==null&&previous?.total_usd?delta/previous.total_usd*100:null}})})
const comparisonChart=computed(()=>({labels:comparisonRows.value.map(m=>String(m.year)),datasets:[{label:seller.value||t('sales'),data:comparisonRows.value.map(m=>m.total_usd),backgroundColor:comparisonRows.value.map((m,i)=>m.partial?'#93c5fd':palette[i%palette.length]),borderRadius:7,maxBarThickness:95}]}))
const lineOptions=computed<ChartOptions<'line'>>(()=>({locale:locale.value,responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:true,position:'bottom',labels:{usePointStyle:true,boxWidth:7,padding:18}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${usd(c.parsed.y)}`}}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,grid:{color:'#eef2f7'},ticks:{callback:v=>Number(v).toLocaleString(locale.value,{notation:'compact'})}}}}))
const barOptions=computed<ChartOptions<'bar'>>(()=>({locale:locale.value,responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>usd(c.parsed.y)}}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,grid:{color:'#eef2f7'},ticks:{callback:v=>Number(v).toLocaleString(locale.value,{notation:'compact'})}}}}))
async function load(){const request=++sequence;loading.value=true;error.value='';try{const result=await salesBi.overview({year:year.value||undefined,month:month.value||undefined,seller:seller.value||undefined});if(request===sequence)data.value=result}catch(e){if(request===sequence)error.value=explain(e)}finally{if(request===sequence)loading.value=false}}
async function refresh(){refreshing.value=true;try{await salesBi.sync();notice.value='syncRequested';status.value=await salesBi.status()}catch(e){error.value=explain(e)}finally{refreshing.value=false}}
async function openConfig(){try{config.value=(await salesBi.config())||config.value;configOpen.value=true}catch(e){error.value=explain(e)}}
async function saveConfig(){saving.value=true;try{await salesBi.save({...config.value,current_year:config.value.current_year||null,current_month:config.value.current_month||null});configOpen.value=false;notice.value='sourcesSaved';status.value=await salesBi.status()}catch(e){error.value=explain(e)}finally{saving.value=false}}
function exportCsv(){const cell=(v:unknown)=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[[t('year'),t('month'),t('seller'),t('totalUsd'),t('status'),t('source')],...visibleMonths.value.map(m=>[m.year,monthNames.value[m.month-1],seller.value||t('allTeam'),m.total_usd?.toLocaleString(locale.value,{useGrouping:false,minimumFractionDigits:2,maximumFractionDigits:2}),m.partial?t('ongoing'):t('monthly'),m.filename])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='eleven-resumo-vendas.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(async()=>{try{const [initial,state]=await Promise.all([salesBi.overview({}),salesBi.status()]);data.value=initial;status.value=state;applyDashboardLink(initial);compareYears.value=initial.years.slice(0,3);await load()}catch(e){error.value=explain(e)}if(disposed)return;timer=setInterval(async()=>{if(polling)return;polling=true;try{const state=await salesBi.status();const changed=state.finished_at!==status.value?.finished_at;status.value=state;if(changed){if(!data.value?.years.length){const initial=await salesBi.overview({});applyDashboardLink(initial);compareYears.value=initial.years.slice(0,3)}await load()}}catch{ /* Retain the visible data during a temporary outage. */ }finally{polling=false}},10000)})
onUnmounted(()=>{disposed=true;clearInterval(timer);sequence++})
</script>

